raw_response:
{
  "interface": {
    "mode": "stdin_stdout",
    "signature": "stdin -> stdout"
  },
  "preconditions": [
    {
      "id": "N_bounds",
      "expression": "3 <= N <= 1000",
      "description": "The number of integers in the sequence is between 3 and 1000."
    },
    {
      "id": "Q_bounds",
      "expression": "1 <= Q <= 1000",
      "description": "There are between 1 and 1000 queries."
    },
    {
      "id": "Bi,j_bounds",
      "expression": "0 <= Bi,j <= 5000",
      "description": "The matrix entries are between 0 and 5000."
    },
    {
      "id": "p_bounds",
      "expression": "1 <= p <= N",
      "description": "The row and column to be changed is between 1 and N."
    },
    {
      "id": "Fi_bounds",
      "expression": "0 <= Fi <= 5000",
      "description": "The new values for the matrix entries are between 0 and 5000."
    }
  ],
  "postconditions": [
    {
      "id": "output_sequence",
      "expression": "output[0] == initial_sequence",
      "description": "The first output line is the lexicographically smallest sequence that fits the initial matrix."
    },
    {
      "id": "output_sequences",
      "expression": "output[i+1] == sequence_after_query(i)",
      "description": "Each subsequent output line is the sequence that fits the matrix after the corresponding query."
    }
  ],
  "invariants": []
}
